// SPDX-License-Identifier: Apache-2.0

/**
 * dsh-type-tune — host half.
 *
 * Three jobs, none of which need the Host settings machinery (so this half
 * never touches schemastery, `configForms`, or the settings namespace split
 * between the 0.1.5 and 0.1.7 host lines):
 *
 * 1. Scan for user font files. `<plugin>/fonts/` is the primary drop folder
 *    (created on boot, with a README inside), and `$DSH_HOME/fonts/` is a
 *    second, plugin-replacement-proof location. `.ttf`/`.otf` family names are
 *    read from the font's own `name` table; `.woff`/`.woff2` fall back to the
 *    file name. TrueType/OpenType *collections* (`.ttc`/`.otc`) are rejected
 *    with a reason, because browsers cannot load them through `@font-face`.
 * 2. Serve them to the browser half over a `prefix` route on the host
 *    webserver: a manifest, the font bytes, and the shared style state.
 * 3. Register the `/style` chat command against the shared state file, so
 *    `/style recover`, `/style preset …`, `/style contrast …` and friends work
 *    from the conversation. The browser half polls the state route, so a
 *    command lands on the page within about a second.
 *
 * Durability: the state lives in `$DSH_HOME/type-tune.json` (NOT in
 * localStorage), which makes one source of truth for both writers — this
 * command and the settings card.
 *
 * @module dsh-type-tune
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";

/** This package's directory (the folder holding `fonts/`). */
const PLUGIN_DIR = path.dirname(fileURLToPath(import.meta.url));
/** Prefix route everything in this plugin lives under. */
const ROUTE_BASE = "/dsh-type-tune";
/** Drop-folder name, in the plugin directory and under `$DSH_HOME`. */
const FONT_DIR_NAME = "fonts";
/** Extensions a browser can load through `@font-face`. */
const SUPPORTED_EXT = new Set([".ttf", ".otf", ".woff", ".woff2"]);
/** Extensions that are real font files but unusable in the browser. */
const COLLECTION_EXT = new Set([".ttc", ".otc"]);
const MIME_BY_EXT = { ".ttf": "font/ttf", ".otf": "font/otf", ".woff": "font/woff", ".woff2": "font/woff2" };
/** Largest font this half will read for name parsing. */
const MAX_FONT_BYTES = 64 * 1024 * 1024;
/** Largest accepted POST body. */
const BODY_LIMIT = 64 * 1024;
/** How many custom families the manifest will carry. */
const MAX_FONTS = 200;

/**
 * The presets, mirrored from the browser half's `PRESETS`.
 *
 * This is the ONE intentional duplication in the plugin: `/style preset` runs
 * on the host, which cannot import the browser bundle. `dev/test-host.mjs`
 * cross-checks the two id sets, so they cannot drift silently.
 */
export const PRESETS = {
	nebula: { contrast: 3, halo: 2 },
	reading: { contrast: 2, halo: 1, linkBold: true, linkUnderline: true },
	neon: { contrast: 2, fx: "rainbow-edge", fxTargets: ["heading", "strong"], fxSpeed: 5 },
	softgrad: { contrast: 2, fx: "gradient-fill", fxTargets: ["heading"], fxSpeed: 8 }
};

/**
 * The resolved DSH home, matching `@deepseek-ai/dsh-home-paths`: an explicit
 * `$DSH_HOME` (when set and non-blank) wins, otherwise `~/.dsh`.
 * @returns {string} absolute home directory.
 */
export function dshHome() {
	const fromEnv = process.env.DSH_HOME;
	if (typeof fromEnv === "string" && fromEnv.trim() !== "") return fromEnv.trim();
	return path.join(os.homedir(), ".dsh");
}

/**
 * The folders scanned for user fonts, in precedence order.
 * @returns {string[]} absolute directories.
 */
export function fontDirs() {
	return [path.join(PLUGIN_DIR, FONT_DIR_NAME), path.join(dshHome(), FONT_DIR_NAME)];
}

/** The shared state file both writers use. @returns {string} absolute path. */
export function stateFile() {
	return path.join(dshHome(), "type-tune.json");
}

//#region dsh-type-tune(host): sfnt family names

/**
 * Make a font family name safe to drop into a quoted CSS string.
 * @param {unknown} raw - candidate name.
 * @returns {string} the cleaned name, or "" when nothing survives.
 */
export function normalizeFamily(raw) {
	if (typeof raw !== "string") return "";
	const cleaned = raw
		// Quotes, backslashes and braces would escape the @font-face declaration.
		.replace(/["'\\{}<>;]/g, "")
		// Control characters become spaces (NOT nothing): a name carrying a line
		// break must read "Line Break", not be silently spliced into "LineBreak".
		.replace(/[\u0000-\u001f\u007f]/g, " ")
		.replace(/\s+/g, " ")
		.trim();
	return cleaned.slice(0, 80);
}

/**
 * Read the family name out of an sfnt (`ttf`/`otf`) `name` table.
 *
 * Deliberately minimal and fully bounds-checked: a truncated or hostile file
 * must return null, never throw. Typographic family (nameID 16) beats the
 * legacy family (nameID 1); Windows/Unicode records beat Macintosh records.
 * @param {Buffer} buf - the whole font file.
 * @returns {string | null} the family name, or null when unreadable.
 */
export function readSfntFamily(buf) {
	try {
		if (!Buffer.isBuffer(buf) || buf.length < 12) return null;
		const sfntVersion = buf.readUInt32BE(0);
		// 'ttcf' — a collection: a browser cannot load it, so no family is needed.
		if (sfntVersion === 0x74746366) return null;
		const numTables = buf.readUInt16BE(4);
		if (numTables <= 0 || numTables > 512) return null;

		let nameOffset = -1;
		for (let i = 0; i < numTables; i += 1) {
			const record = 12 + i * 16;
			if (record + 16 > buf.length) break;
			if (buf.readUInt32BE(record) === 0x6e616d65) { // 'name'
				nameOffset = buf.readUInt32BE(record + 8);
				break;
			}
		}
		if (nameOffset < 0 || nameOffset + 6 > buf.length) return null;

		const count = buf.readUInt16BE(nameOffset + 2);
		const storage = nameOffset + buf.readUInt16BE(nameOffset + 4);
		/** @type {{ score: number, text: string } | null} */
		let best = null;

		for (let i = 0; i < count; i += 1) {
			const record = nameOffset + 6 + i * 12;
			if (record + 12 > buf.length) break;
			const platformID = buf.readUInt16BE(record);
			const languageID = buf.readUInt16BE(record + 4);
			const nameID = buf.readUInt16BE(record + 6);
			const length = buf.readUInt16BE(record + 8);
			const offset = buf.readUInt16BE(record + 10);
			// Only the two family ids carry what @font-face needs.
			if (nameID !== 1 && nameID !== 16) continue;
			if (length === 0 || length > 512) continue;
			const start = storage + offset;
			if (start < 0 || start + length > buf.length) continue;

			const slice = buf.subarray(start, start + length);
			let text;
			if (platformID === 3 || platformID === 0) {
				if (length % 2 !== 0) continue;
				// UTF-16BE: rebuild code unit by code unit (Buffer only does LE).
				let decoded = "";
				for (let at = 0; at < slice.length; at += 2) decoded += String.fromCharCode(slice.readUInt16BE(at));
				text = decoded;
			} else if (platformID === 1) {
				text = slice.toString("latin1");
			} else {
				continue;
			}
			const family = normalizeFamily(text.replace(/\(.*?\)/g, ""));
			if (family === "") continue;

			// Rank: typographic family > legacy family; Windows > Macintosh;
			// en-US > any other language.
			let score = nameID === 16 ? 100 : 0;
			if (platformID === 3 || platformID === 0) score += 20;
			if (languageID === 0x0409) score += 5;
			if (best === null || score > best.score) best = { score, text: family };
		}
		return best === null ? null : best.text;
	} catch {
		return null;
	}
}

/**
 * Derive a readable family name from a file name, for formats whose tables this
 * half does not decode (`woff`/`woff2`).
 * @param {string} fileName - the font file's base name.
 * @returns {string} a cleaned family name.
 */
export function familyFromFileName(fileName) {
	const base = path.basename(fileName, path.extname(fileName));
	return normalizeFamily(base.replace(/[_-]+/g, " ")) || normalizeFamily(base);
}
//#endregion

//#region dsh-type-tune(host): scanning

/** Cache of parsed family names, keyed by path + size + mtime. */
const familyCache = new Map();

/**
 * Parse (or reuse) one font file's family name.
 * @param {string} filePath - absolute font path.
 * @param {fs.Stats} stats - that file's stats.
 * @returns {{ family: string | null, collection: boolean }} the parsed family
 * and whether the file is a TrueType collection disguised as `.ttf`/`.otf`.
 */
function familyOf(filePath, stats) {
	const key = `${filePath}:${String(stats.size)}:${String(stats.mtimeMs)}`;
	if (familyCache.has(key)) return familyCache.get(key);
	const result = { family: null, collection: false };
	try {
		const ext = path.extname(filePath).toLowerCase();
		if (ext === ".ttf" || ext === ".otf") {
			if (stats.size <= MAX_FONT_BYTES) {
				const buf = fs.readFileSync(filePath);
				// `SansSerifCollection.ttf` and friends are TrueType collections
				// wearing a `.ttf` suffix: browsers cannot load them either.
				if (buf.length >= 4 && buf.readUInt32BE(0) === 0x74746366) {
					result.collection = true;
				} else {
					result.family = readSfntFamily(buf);
				}
			}
		}
	} catch {
		result.family = null;
	}
	if (!result.collection && (result.family === null || result.family === "")) result.family = familyFromFileName(filePath);
	// Keep the cache from growing without bound across a long-lived process.
	if (familyCache.size > 500) familyCache.clear();
	familyCache.set(key, result);
	return result;
}

/**
 * Lowercase, punctuation-free form used to compare a file name against a family
 * name ("My Font" / "my_font-Bold.ttf" both collapse to "myfontbold"-style keys).
 * @param {string} text - file name or family name.
 * @returns {string} comparison slug.
 */
function slug(text) {
	return String(text).toLowerCase().replace(/[^a-z0-9]+/g, "");
}

/**
 * Scan the drop folders for loadable fonts.
 *
 * Never throws: an unreadable directory simply contributes nothing, and every
 * skipped file is reported with a reason so the UI can explain itself.
 * @param {string[]} [dirs] - directories to scan; defaults to {@link fontDirs}.
 * @returns {{ fonts: Array<{id: string, family: string, file: string, dir: string, format: string, bytes: number}>, rejected: Array<{file: string, reason: string}> }}
 */
export function scanFonts(dirs = fontDirs()) {
	/** Every loadable candidate, before duplicate-family arbitration. */
	const candidates = [];
	/** @type {Array<{file:string,reason:string}>} */
	const rejected = [];

	/** Cap the total files inspected, so a directory with tens of thousands of
	 * entries cannot make the manifest handler read (and parse) every one. */
	const SCAN_BUDGET = 1000;
	let scanned = 0;

	outer:
	for (const dir of dirs) {
		let entries;
		try {
			entries = fs.readdirSync(dir, { withFileTypes: true });
		} catch {
			continue; // folder absent (or unreadable): nothing to report
		}
		// Stable order so the manifest does not shuffle between requests.
		entries.sort((a, b) => a.name.localeCompare(b.name));
		for (const entry of entries) {
			scanned += 1;
			if (scanned > SCAN_BUDGET) break outer;
			if (!entry.isFile() || entry.name.startsWith(".")) continue;
			const ext = path.extname(entry.name).toLowerCase();
			const filePath = path.join(dir, entry.name);
			if (COLLECTION_EXT.has(ext)) {
				rejected.push({ file: entry.name, reason: "字体集合（.ttc/.otc）浏览器无法通过 @font-face 加载，请改用 .ttf/.otf/.woff2" });
				continue;
			}
			if (!SUPPORTED_EXT.has(ext)) {
				if (ext !== ".txt" && ext !== ".md") rejected.push({ file: entry.name, reason: `不支持的扩展名 ${ext || "(无)"}` });
				continue;
			}
			let stats;
			try {
				stats = fs.statSync(filePath);
			} catch {
				continue;
			}
			if (stats.size === 0) {
				rejected.push({ file: entry.name, reason: "空文件" });
				continue;
			}
			const parsed = familyOf(filePath, stats);
			if (parsed.collection) {
				rejected.push({ file: entry.name, reason: "该 .ttf/.otf 实为 TrueType 字体集合（TTC），浏览器无法通过 @font-face 加载" });
				continue;
			}
			const family = parsed.family;
			if (family === null || family === "") {
				rejected.push({ file: entry.name, reason: "无法确定字体家族名（文件可能已损坏）" });
				continue;
			}
			const hash = createHash("sha1")
				.update(`${entry.name}:${String(stats.size)}:${String(Math.round(stats.mtimeMs))}`)
				.digest("hex")
				.slice(0, 8);
			const familySlug = slug(family).slice(0, 40) || "font";
			candidates.push({
				id: `${familySlug}-${hash}`,
				family,
				file: entry.name,
				dir,
				format: ext.slice(1),
				bytes: stats.size,
				// A file named after its own family is the better keeper.
				exact: slug(path.basename(entry.name, ext)) === slug(family)
			});
		}
	}

	// One family, one slot: the file whose name matches the family wins, then the
	// shorter name, then the earlier name. Deterministic, and the losers are
	// reported instead of silently vanishing.
	const byFamily = new Map();
	for (const candidate of candidates) {
		const list = byFamily.get(candidate.family);
		if (list === undefined) byFamily.set(candidate.family, [candidate]);
		else list.push(candidate);
	}
	const fonts = [];
	for (const [family, list] of byFamily) {
		list.sort((a, b) => (Number(b.exact) - Number(a.exact)) || (a.file.length - b.file.length) || a.file.localeCompare(b.file));
		fonts.push(list[0]);
		for (const loser of list.slice(1)) {
			rejected.push({ file: loser.file, reason: `字体家族「${family}」已由 ${list[0].file} 提供` });
		}
	}
	fonts.sort((a, b) => a.family.localeCompare(b.family));
	return { fonts: fonts.slice(0, MAX_FONTS), rejected };
}

/**
 * A short signature of the current font set, so the browser half can tell
 * whether a refresh changed anything.
 * @param {Array<{id: string, bytes: number}>} fonts - scanned fonts.
 * @returns {string} signature.
 */
export function fontSignature(fonts) {
	return createHash("sha1").update(fonts.map((f) => `${f.id}:${String(f.bytes)}`).join("|")).digest("hex").slice(0, 12);
}
//#endregion

//#region dsh-type-tune(host): shared state

/**
 * Read the shared state.
 *
 * `present` distinguishes "no state file yet" from "the user explicitly cleared
 * every override": the browser half must keep its own stored config in the first
 * case (an upgrade must not wipe existing settings) and fall back to defaults in
 * the second.
 * @returns {{ revision: number, config: object | null, updatedAt: string | null, present: boolean }} state.
 */
export function loadState() {
	/** @type {{ revision: number, config: object | null, updatedAt: string | null, present: boolean }} */
	const absent = { revision: 0, config: null, updatedAt: null, present: false };
	let raw;
	try {
		raw = fs.readFileSync(stateFile(), "utf8");
	} catch {
		return absent;
	}
	try {
		const parsed = JSON.parse(raw);
		if (parsed === null || typeof parsed !== "object") return absent;
		const config = parsed.config;
		return {
			revision: Number.isFinite(parsed.revision) ? Math.max(0, Math.floor(parsed.revision)) : 0,
			config: config !== null && typeof config === "object" && !Array.isArray(config) ? config : null,
			updatedAt: typeof parsed.updatedAt === "string" ? parsed.updatedAt : null,
			present: true
		};
	} catch {
		return absent;
	}
}

/**
 * Write the shared state, bumping the revision so pollers notice.
 * @param {object | null} config - the full browser config, or null for defaults.
 * @returns {{ revision: number, config: object | null, updatedAt: string | null, present: boolean }} the stored state.
 */
export function saveState(config) {
	const previous = loadState();
	const next = {
		revision: previous.revision + 1,
		config: config === null || typeof config !== "object" || Array.isArray(config) ? null : config,
		updatedAt: new Date().toISOString(),
		present: true
	};
	try {
		const file = stateFile();
		fs.mkdirSync(path.dirname(file), { recursive: true });
		// Write-then-rename: a crash mid-write can never leave a half state file.
		const temp = `${file}.tmp`;
		fs.writeFileSync(temp, `${JSON.stringify(next, null, 2)}\n`, "utf8");
		fs.renameSync(temp, file);
	} catch {
		// Unwritable home: the browser keeps its own localStorage copy.
	}
	return next;
}

/**
 * Merge a partial patch onto the stored config, honouring the null (defaults)
 * base and dropping unknown keys is left to the browser half's normalizer —
 * this half only guarantees the object stays a plain, bounded JSON object.
 * @param {object} patch - the keys to set.
 * @returns {{ revision: number, config: object | null, updatedAt: string | null }} the stored state.
 */
export function patchState(patch) {
	const current = loadState().config;
	const merged = { ...(current ?? {}), ...patch };
	return saveState(merged);
}
//#endregion

//#region dsh-type-tune(host): /style command

/** One-line summary of a state's most visible settings. */
function summarize(config) {
	if (config === null) return "全部默认（未做任何覆盖）";
	const bits = [];
	if (config.contrast !== undefined) bits.push(`对比 ${String(config.contrast)}`);
	if (config.halo !== undefined) bits.push(`光晕 ${String(config.halo)}`);
	if (config.uiFont !== undefined) bits.push(`界面字体 ${String(config.uiFont)}`);
	if (config.codeFont !== undefined) bits.push(`代码字体 ${String(config.codeFont)}`);
	if (config.sizeOffset !== undefined) bits.push(`字号偏移 ${String(config.sizeOffset)}`);
	if (config.fx !== undefined) bits.push(`特效 ${String(config.fx)}`);
	if (config.linkBold === true || config.linkUnderline === true) bits.push("链接强调");
	if (config.previewVisible === false) bits.push("预览窗关");
	return bits.length === 0 ? "全部默认" : bits.join(" · ");
}

const HELP = [
	"/style — 查看当前状态",
	"/style fonts — 列出发现的自定义字体与被跳过的文件",
	"/style preset <off|nebula|reading|neon|softgrad> — 应用预设",
	"/style contrast <0-3> — 对比增强档位",
	"/style halo <0-3> — 文字光晕强度",
	"/style fx <off|rainbow-edge|gradient-fill> — 特效类型",
	"/style links <bold|underline|both|off> — 链接加粗/下划线",
	"/style font <家族名|auto> — 界面字体",
	"/style code <家族名|auto> — 代码字体",
	"/style size <-2..4> — 正文字号偏移",
	"/style preview <on|off> — 预览小窗开关",
	"/style recover — 恢复默认（等于清空所有覆盖）"
].join("\n");

/**
 * Turn one `/style` invocation into a reply.
 *
 * Pure with respect to the arguments it is given: every branch either reads the
 * font folders or the state file and, on success, writes the state file.
 * @param {string} rawInput - everything after `/style`.
 * @returns {{ kind: 'success' | 'error', text: string }} the command result.
 */
export function runStyleCommand(rawInput) {
	const tokens = String(rawInput ?? "").trim().split(/\s+/).filter(Boolean);
	const sub = (tokens[0] ?? "").toLowerCase();
	const rest = tokens.slice(1);
	const arg = rest.join(" ");

	const reply = (text) => ({ kind: "success", text });
	const fail = (text) => ({ kind: "error", text });

	if (sub === "" || sub === "status") {
		const state = loadState();
		const { fonts } = scanFonts();
		return reply([
			`字体与可读性：${summarize(state.config)}`,
			`自定义字体：${String(fonts.length)} 个${fonts.length > 0 ? `（${fonts.slice(0, 6).map((f) => f.family).join("、")}${fonts.length > 6 ? " 等" : ""}）` : ""}`,
			"改完约 1 秒内在页面上生效，无需刷新。",
			"输入 /style help 查看全部命令。"
		].join("\n"));
	}
	if (sub === "help" || sub === "-h" || sub === "--help") return reply(HELP);

	if (sub === "recover" || sub === "reset" || sub === "default") {
		saveState(null);
		return reply("已恢复默认：所有覆盖已清空（对比、光晕、字体、字号、特效、链接样式、预览窗）。约 1 秒内在页面上生效。");
	}

	if (sub === "fonts") {
		const { fonts, rejected } = scanFonts();
		const lines = [`扫描目录：`, ...fontDirs().map((d) => `  ${d}`), `共发现 ${String(fonts.length)} 个可用字体：`];
		for (const font of fonts.slice(0, 40)) lines.push(`  ${font.family}  (${font.file}, ${font.format}, ${String(Math.round(font.bytes / 1024))} KB)`);
		if (fonts.length > 40) lines.push(`  … 另有 ${String(fonts.length - 40)} 个`);
		if (rejected.length > 0) {
			lines.push("", `跳过了 ${String(rejected.length)} 个文件：`);
			for (const item of rejected.slice(0, 15)) lines.push(`  ${item.file} — ${item.reason}`);
		}
		lines.push("", "把字体文件放进上面的目录后刷新页面即可看到。");
		return reply(lines.join("\n"));
	}

	if (sub === "preset") {
		const ids = Object.keys(PRESETS).concat(["off"]);
		if (!ids.includes(arg)) return fail(`未知预设「${arg || "(空)"}」。可用：${ids.join(" | ")}`);
		if (arg === "off") {
			saveState(null);
			return reply("已关闭全部覆盖（等同 /style recover）：对比、光晕、字体、字号、特效、链接样式与预览窗全部回到默认。");
		}
		patchState(PRESETS[arg]);
		return reply(`已应用预设「${arg}」：${summarize(loadState().config)}`);
	}

	const intArg = (label, min, max) => {
		const value = Number(arg);
		if (arg === "" || !Number.isFinite(value) || !Number.isInteger(value) || value < min || value > max) return null;
		return value;
	};

	if (sub === "contrast" || sub === "halo") {
		const value = intArg(sub, 0, 3);
		if (value === null) return fail(`用法：/style ${sub} <0-3>`);
		patchState({ [sub]: value });
		return reply(`已设置${sub === "contrast" ? "对比增强" : "文字光晕"} = ${String(value)}`);
	}

	if (sub === "size") {
		const value = intArg(sub, -2, 4);
		if (value === null) return fail("用法：/style size <-2..4>（0 表示不干预「外观」里的对话字号）");
		patchState({ sizeOffset: value });
		return reply(`已设置正文字号偏移 = ${value > 0 ? `+${String(value)}` : String(value)} px`);
	}

	if (sub === "fx") {
		const modes = ["off", "rainbow-edge", "gradient-fill"];
		if (!modes.includes(arg)) return fail(`用法：/style fx <${modes.join("|")}>`);
		patchState({ fx: arg });
		return reply(arg === "off" ? "已关闭字体特效" : `已开启特效「${arg}」`);
	}

	if (sub === "links") {
		const modes = {
			off: { linkBold: false, linkUnderline: false },
			bold: { linkBold: true, linkUnderline: false },
			underline: { linkBold: false, linkUnderline: true },
			both: { linkBold: true, linkUnderline: true }
		};
		if (!(arg in modes)) return fail(`用法：/style links <${Object.keys(modes).join("|")}>`);
		patchState(modes[arg]);
		return reply(`链接样式已设为「${arg}」`);
	}

	if (sub === "font" || sub === "code") {
		if (arg === "") return fail(`用法：/style ${sub} <家族名|auto>（用 /style fonts 查看可用家族名）`);
		const key = sub === "font" ? "uiFont" : "codeFont";
		if (arg === "auto" || arg === "默认" || arg === "default") {
			patchState({ [key]: "auto" });
			return reply(`已把${sub === "font" ? "界面" : "代码"}字体恢复为默认`);
		}
		// Custom families are stored under their real name so @font-face matches.
		patchState({ [key]: arg });
		return reply(`已把${sub === "font" ? "界面" : "代码"}字体设为「${arg}」。若是自定义字体，请确认它出现在 /style fonts 列表里。`);
	}

	if (sub === "preview") {
		if (arg !== "on" && arg !== "off") return fail("用法：/style preview <on|off>");
		patchState({ previewVisible: arg === "on" });
		return reply(arg === "on" ? "预览小窗已显示" : "预览小窗已隐藏");
	}

	return fail(`未知子命令「${sub}」。\n${HELP}`);
}
//#endregion

//#region dsh-type-tune(host): HTTP routes

/**
 * Read a small request body.
 * @param {import('node:http').IncomingMessage} req - the request.
 * @returns {Promise<string | null>} the body, or null when too large / broken.
 */
function readBody(req) {
	return new Promise((resolve) => {
		let size = 0;
		/** @type {Buffer[]} */
		const chunks = [];
		req.on("data", (chunk) => {
			size += chunk.length;
			if (size > BODY_LIMIT) {
				resolve(null);
				req.destroy();
				return;
			}
			chunks.push(chunk);
		});
		req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
		req.on("error", () => resolve(null));
	});
}

/**
 * Whether a mutating request comes from the very page this server serves.
 *
 * The routes are unauthenticated by design (the webserver is loopback-only
 * unless an operator deliberately binds `0.0.0.0`), so writes are additionally
 * gated on a same-origin `Origin` and a JSON content type — a cross-site form
 * or `fetch` cannot satisfy both without a CORS preflight this server never
 * grants.
 * @param {import('node:http').IncomingMessage} req - the request.
 * @returns {boolean} whether the write is allowed.
 */
function sameOriginJson(req) {
	const type = String(req.headers["content-type"] ?? "");
	if (!type.toLowerCase().includes("application/json")) return false;
	const origin = req.headers.origin;
	if (typeof origin !== "string" || origin === "") return true; // curl / same-origin without Origin
	try {
		return new URL(origin).host === req.headers.host;
	} catch {
		return false;
	}
}

/** Send a JSON response. */
function sendJson(res, status, payload) {
	const body = Buffer.from(`${JSON.stringify(payload)}\n`, "utf8");
	res.writeHead(status, {
		"content-type": "application/json; charset=utf-8",
		"content-length": String(body.length),
		"cache-control": "no-store"
	});
	res.end(body);
}

/**
 * Build the manifest the browser half reads on load and on every rescan.
 * @returns {object} the manifest payload.
 */
function manifestPayload() {
	const { fonts, rejected } = scanFonts();
	return {
		base: ROUTE_BASE,
		signature: fontSignature(fonts),
		dirs: fontDirs(),
		fonts,
		rejected,
		state: loadState()
	};
}

/**
 * Handle one request under {@link ROUTE_BASE}. Never throws to the caller: the
 * webserver answers a throwing handler with a 400 and a warning, which would be
 * a silent failure for the page.
 * @param {import('node:http').IncomingMessage} req - the request.
 * @param {import('node:http').ServerResponse} res - the response.
 * @returns {Promise<void>} resolves once the response is owned.
 */
export async function handleRoute(req, res) {
	try {
		const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "127.0.0.1"}`);
		const pathname = url.pathname;
		const method = (req.method ?? "GET").toUpperCase();

		if (pathname === `${ROUTE_BASE}/manifest` && method === "GET") {
			sendJson(res, 200, manifestPayload());
			return;
		}
		if (pathname === `${ROUTE_BASE}/state`) {
			if (method === "GET") {
				sendJson(res, 200, loadState());
				return;
			}
			if (method === "POST") {
				if (!sameOriginJson(req)) {
					sendJson(res, 403, { error: "forbidden" });
					return;
				}
				const body = await readBody(req);
				if (body === null) {
					sendJson(res, 413, { error: "body too large" });
					return;
				}
				let parsed;
				try {
					parsed = JSON.parse(body);
				} catch {
					sendJson(res, 400, { error: "invalid json" });
					return;
				}
				if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
					sendJson(res, 400, { error: "expected a config object" });
					return;
				}
				const mode = parsed.mode === "recover" ? "recover" : "set";
				const state = mode === "recover" ? saveState(null) : saveState(parsed.config);
				sendJson(res, 200, state);
				return;
			}
			sendJson(res, 405, { error: "method not allowed" });
			return;
		}
		if (pathname.startsWith(`${ROUTE_BASE}/font/`) && method === "GET") {
			const id = decodeURIComponent(pathname.slice(`${ROUTE_BASE}/font/`.length));
			if (!/^[a-z0-9-]{1,80}$/.test(id)) {
				sendJson(res, 400, { error: "bad id" });
				return;
			}
			const { fonts } = scanFonts();
			const font = fonts.find((entry) => entry.id === id);
			if (font === undefined) {
				sendJson(res, 404, { error: "unknown font" });
				return;
			}
			const filePath = path.join(font.dir, font.file);
			const ext = path.extname(font.file).toLowerCase();
			res.writeHead(200, {
				"content-type": MIME_BY_EXT[ext] ?? "application/octet-stream",
				"content-length": String(font.bytes),
				// The id carries a content hash, so the bytes behind it never change.
				"cache-control": "public, max-age=31536000, immutable"
			});
			const stream = fs.createReadStream(filePath);
			stream.on("error", () => res.destroy());
			stream.pipe(res);
			return;
		}
		sendJson(res, 404, { error: "not found" });
	} catch (error) {
		try {
			sendJson(res, 500, { error: String(error) });
		} catch {
			// Headers already sent: nothing left to do.
		}
	}
}
//#endregion

//#region dsh-type-tune(host): plugin body

/** Seed the drop folders so the user has somewhere obvious to put files. */
function ensureFontDirs() {
	for (const dir of fontDirs()) {
		try {
			fs.mkdirSync(dir, { recursive: true });
		} catch {
			continue;
		}
		const readme = path.join(dir, "README.txt");
		try {
			if (!fs.existsSync(readme)) {
				fs.writeFileSync(
					readme,
					[
						"把字体文件直接放进这个文件夹，然后刷新 DSH 页面即可在「字体与可读性」里选到它们。",
						"",
						"支持：.ttf / .otf / .woff / .woff2",
						"不支持：.ttc / .otc（字体集合，浏览器无法通过 @font-face 加载）",
						"",
						".ttf/.otf 会读取字体自带的家族名；.woff/.woff2 用文件名作为家族名。",
						"同名家族只保留第一个文件。",
						"",
						"也可以放在 " + path.join(dshHome(), FONT_DIR_NAME) + " —— 那个目录不会随插件更新而丢失。"
					].join("\n") + "\n",
					"utf8"
				);
			}
		} catch {
			// A read-only folder is not worth failing the boot over.
		}
	}
}

/**
 * Empty service precondition: this half must never park on a missing service.
 * The webserver (web hosts) and the command service are attached imperatively.
 */
export const inject = [];

/**
 * Host plugin body.
 *
 * Every step is wrapped so that a failure here degrades the feature instead of
 * failing the profile's boot: the font folders and routes only exist on a host
 * that composes a webserver, and the command only on one that composes
 * `commands`.
 * @param {import('@deepseek-ai/cordis').Context} ctx - host context.
 */
export function apply(ctx) {
	try {
		ensureFontDirs();
	} catch (error) {
		ctx.logger?.warn?.(`type-tune: font folder setup failed: ${String(error)}`);
	}

	try {
		ctx.inject(["webServer"], (webCtx) => {
			const routes = [
				{ kind: "prefix", path: ROUTE_BASE, handler: handleRoute }
			];
			for (const route of routes) {
				webCtx.effect(() => webCtx.webServer.register(route), `dsh-type-tune: route ${route.path}`);
			}
		});
	} catch (error) {
		ctx.logger?.warn?.(`type-tune: web routes unavailable: ${String(error)}`);
	}

	try {
		ctx.inject(["commands"], (commandCtx) => {
			commandCtx.commands.register({
				name: "style",
				description: "字体与可读性：查看/切换自定义字体、对比度与特效",
				input: { hint: "[status|fonts|preset|contrast|halo|fx|links|font|code|size|preview|recover]" },
				handler: (invocation) => runStyleCommand(invocation?.rawInput ?? "")
			});
		});
	} catch (error) {
		ctx.logger?.warn?.(`type-tune: /style command unavailable: ${String(error)}`);
	}
}
