				closeBtn.addEventListener("click", () => setPreviewVisible(false));
				head.appendChild(closeBtn);

				const body = document.createElement("div");
				body.className = "dtt-body";

				const h2 = document.createElement("h2");
				h2.textContent = "预览标题 123";
				body.appendChild(h2);

				const p1 = document.createElement("p");
				p1.textContent = "中英混排 mixed 123：设计字体，正文段落示例。";
				body.appendChild(p1);

				const p2 = document.createElement("p");
				const a = document.createElement("a");
				a.href = "#";
				a.textContent = "这是一个超链接";
				p2.appendChild(a);
				p2.appendChild(document.createTextNode(" 与 "));
				const strong = document.createElement("strong");
				strong.textContent = "强调文字";
				p2.appendChild(strong);
				p2.appendChild(document.createTextNode("，以及 "));
				const code = document.createElement("code");
				code.textContent = "inline_code()";
				p2.appendChild(code);
				body.appendChild(p2);

				const bq = document.createElement("blockquote");
				bq.textContent = "引用块示例：站在巨人的肩膀上。";
				body.appendChild(bq);

				const caption = document.createElement("div");
				caption.className = "dtt-caption";
				caption.textContent = "次级说明文字 · 对比度 ";
				const badge = document.createElement("span");
				badge.className = "dtt-badge";
				caption.appendChild(badge);
				body.appendChild(caption);

